/**
 * Application tables (Phase 2 foundation + stubs for later phases).
 *
 * Auth/org tables (users, sessions, accounts, verifications, organizations,
 * members, invitations) live in ./auth-schema.ts and are generated by the
 * Better Auth CLI (`npx @better-auth/cli generate`) so their shape always
 * matches exactly what the Better Auth Drizzle adapter expects. Do not
 * hand-edit that file's table definitions; re-run the generator instead.
 */
import {
  pgTable,
  text,
  timestamp,
  uuid,
  jsonb,
  varchar,
  integer,
  boolean,
} from "drizzle-orm/pg-core";
import { organizations, users } from "./auth-schema";

/**
 * Websites a tenant has registered for crawling/SEO auditing.
 *
 * Ownership verification (Phase 3): `verificationToken` is generated when
 * the website row is created; the user is shown it and asked to either
 * publish it as a `<meta name="seo-platform-verification" content="...">`
 * tag on their homepage or as a `_seo-platform-verify` DNS TXT record.
 * `verifiedAt`/`verificationMethod` are set only once our own code has
 * actually fetched the page (or looked up the TXT record) and found the
 * token — see src/lib/ownership-verification.ts. This is a real, if
 * basic, check: it is NOT a checkbox the user can tick themselves.
 *
 * Per spec, a manual one-off audit is allowed on an unverified site (see
 * INTEGRATION_ARCHITECTURE.md for the rationale); verification is only
 * required before scheduled/extensive scans, which are out of scope until
 * Phase 5.
 *
 * Phase 5 scheduling fields:
 *  - `auditSchedule`: none | daily | weekly | monthly. Mirrored into a
 *    pg-boss `schedule()` entry keyed by this website's id (see
 *    src/lib/queue.ts#applyWebsiteSchedule) — pg-boss, not a hand-rolled
 *    cron loop, owns firing it.
 *  - `lastScheduledCrawlAt`: when a *scheduled* (non-manual) crawl was last
 *    actually kicked off for this site, used to enforce a minimum interval
 *    between scheduled crawls regardless of how aggressive the cron
 *    expression is (see src/lib/jobs/scheduled-audit.ts).
 *  - `lastHomepageEtag` / `lastHomepageLastModified`: cached conditional-
 *    request validators from the homepage's last scheduled fetch, used for
 *    the cheap "did anything change" pre-check before a full crawl.
 */
export const websites = pgTable("websites", {
  id: uuid("id").primaryKey().defaultRandom(),
  organizationId: text("organization_id")
    .notNull()
    .references(() => organizations.id, { onDelete: "cascade" }),
  url: text("url").notNull(),
  verificationToken: text("verification_token").notNull(),
  verificationMethod: varchar("verification_method", { length: 16 }),
  verifiedAt: timestamp("verified_at", { withTimezone: true }),
  /** none | daily | weekly | monthly */
  auditSchedule: varchar("audit_schedule", { length: 16 })
    .notNull()
    .default("none"),
  lastScheduledCrawlAt: timestamp("last_scheduled_crawl_at", { withTimezone: true }),
  lastHomepageEtag: text("last_homepage_etag"),
  lastHomepageLastModified: text("last_homepage_last_modified"),
  createdAt: timestamp("created_at", { withTimezone: true })
    .notNull()
    .defaultNow(),
});

/**
 * A single crawl run against a website.
 * `options` carries the crawl-time configuration (maxPages, maxDepth,
 * jsRendering, and the test-only SSRF allowlist override — see
 * crawl-safety.ts) so a job is fully reproducible from its stored row.
 *
 * `status` lifecycle (Phase 5 adds `cancelled`): pending -> running ->
 * completed | failed | cancelled.
 * `trigger` (Phase 5): "manual" (user clicked "Run crawl") or "scheduled"
 * (pg-boss's own cron-based `schedule()` fired it) — shown in the job
 * history/observability view.
 * `pgBossJobId` (Phase 5): the id pg-boss's `send()` returned for this
 * row's job, so a "Cancel" action can call `boss.cancel(queue, id)` on the
 * exact underlying job.
 */
export const crawlJobs = pgTable("crawl_jobs", {
  id: uuid("id").primaryKey().defaultRandom(),
  websiteId: uuid("website_id")
    .notNull()
    .references(() => websites.id, { onDelete: "cascade" }),
  status: varchar("status", { length: 32 }).notNull().default("pending"),
  /** manual | scheduled */
  trigger: varchar("trigger", { length: 16 }).notNull().default("manual"),
  pgBossJobId: text("pg_boss_job_id"),
  options: jsonb("options").notNull().default({}),
  error: text("error"),
  createdAt: timestamp("created_at", { withTimezone: true })
    .notNull()
    .defaultNow(),
  startedAt: timestamp("started_at", { withTimezone: true }),
  finishedAt: timestamp("finished_at", { withTimezone: true }),
});

/**
 * An individual technical-SEO issue surfaced by a crawl job.
 *
 * Normalized finding schema (see docs/INTEGRATION_ARCHITECTURE.md): every
 * finding, whether it comes directly from siteone-crawler's analyzer or
 * from our own supplementary rule-engine pass, is mapped into this exact
 * shape so the dashboard/report layer never needs to know which engine
 * produced it. `sourceEngine` + `category` together say which: e.g.
 * sourceEngine="siteone-crawler", category="broken_link" vs.
 * sourceEngine="supplementary-rules", category="duplicate_title".
 */
export const findings = pgTable("findings", {
  id: uuid("id").primaryKey().defaultRandom(),
  crawlJobId: uuid("crawl_job_id")
    .notNull()
    .references(() => crawlJobs.id, { onDelete: "cascade" }),
  websiteId: uuid("website_id")
    .notNull()
    .references(() => websites.id, { onDelete: "cascade" }),
  sourceEngine: varchar("source_engine", { length: 32 }).notNull(),
  url: text("url").notNull(),
  canonicalUrl: text("canonical_url"),
  httpStatus: integer("http_status"),
  severity: varchar("severity", { length: 16 }).notNull(),
  category: varchar("category", { length: 64 }).notNull(),
  title: text("title").notNull(),
  description: text("description").notNull().default(""),
  evidence: jsonb("evidence").notNull().default({}),
  discoveredAt: timestamp("discovered_at", { withTimezone: true })
    .notNull()
    .defaultNow(),
});

/**
 * AI-generated recommendations for a crawl job (Phase 4).
 *
 * Hard requirements this table enforces/supports (see
 * docs/REPORTING.md and src/lib/ai/recommendation-engine.ts):
 *  - `findingIds` is a JSON array of real `findings.id` UUIDs this
 *    recommendation is grounded in. It is populated by OUR code from
 *    the actual finding rows handed to the engine, never by parsing
 *    anything the AI model emitted — so a recommendation can never cite
 *    a finding that doesn't exist, even if the model hallucinates.
 *  - `priority` is derived from the grounding finding(s)' own severity
 *    plus a small, documented category-impact heuristic (see
 *    computePriority in recommendation-engine.ts) — never a fabricated
 *    score.
 *  - `body` is model-generated prose when an AI provider was available,
 *    or a deterministic template when it was not — `metadata.generatedBy`
 *    says which, so nothing here is presented as AI-verified when it
 *    wasn't.
 */
export const aiRecommendations = pgTable("ai_recommendations", {
  id: uuid("id").primaryKey().defaultRandom(),
  crawlJobId: uuid("crawl_job_id")
    .notNull()
    .references(() => crawlJobs.id, { onDelete: "cascade" }),
  websiteId: uuid("website_id")
    .notNull()
    .references(() => websites.id, { onDelete: "cascade" }),
  /**
   * finding_explanation | title_meta_suggestion | internal_linking |
   * structured_data | dev_task | audit_summary
   */
  kind: varchar("kind", { length: 32 }).notNull(),
  /** Real `findings.id` UUIDs this recommendation is grounded in. Never empty. */
  findingIds: jsonb("finding_ids").notNull().default([]),
  /** critical | high | medium | low — derived, see computePriority(). Null only for audit_summary. */
  priority: varchar("priority", { length: 16 }),
  title: text("title").notNull(),
  body: text("body").notNull(),
  /** { generatedBy: "ollama"|"template-fallback", model?, suggestedTitle?, suggestedMetaDescription?, ... } */
  metadata: jsonb("metadata").notNull().default({}),
  createdAt: timestamp("created_at", { withTimezone: true })
    .notNull()
    .defaultNow(),
});

/**
 * A generated report artifact for a website (Phase 4).
 *
 * One `crawl_jobs` row can have up to 4 report rows (one per format);
 * `filePath` is relative to the app's report storage root
 * (STORAGE_REPORTS_DIR / app/storage/reports by default — see
 * src/lib/reports/generate.ts), never an absolute path, so moving the
 * storage root doesn't invalidate existing rows.
 */
export const reports = pgTable("reports", {
  id: uuid("id").primaryKey().defaultRandom(),
  websiteId: uuid("website_id")
    .notNull()
    .references(() => websites.id, { onDelete: "cascade" }),
  crawlJobId: uuid("crawl_job_id")
    .notNull()
    .references(() => crawlJobs.id, { onDelete: "cascade" }),
  format: varchar("format", { length: 16 }).notNull(),
  healthScore: integer("health_score"),
  generatedAt: timestamp("generated_at", { withTimezone: true })
    .notNull()
    .defaultNow(),
  filePath: text("file_path").notNull(),
});

/**
 * An in-app notification (Phase 5), surfaced on the dashboard without any
 * external service required. The default, always-on notifier
 * (src/lib/notifications/notifier.ts) writes one of these whenever a
 * *scheduled* crawl completes with at least one NEW finding (per the
 * before/after diff in src/lib/findings-diff.ts) of medium severity or
 * higher — a manual one-off crawl never generates noise here. An optional
 * SMTP email send (gated on `SMTP_URL`, never required) rides alongside
 * this row but never replaces it.
 */
export const notifications = pgTable("notifications", {
  id: uuid("id").primaryKey().defaultRandom(),
  organizationId: text("organization_id")
    .notNull()
    .references(() => organizations.id, { onDelete: "cascade" }),
  websiteId: uuid("website_id")
    .notNull()
    .references(() => websites.id, { onDelete: "cascade" }),
  crawlJobId: uuid("crawl_job_id").references(() => crawlJobs.id, { onDelete: "cascade" }),
  /** new_findings | ... (room to grow; new_findings is the only kind Phase 5 emits) */
  type: varchar("type", { length: 32 }).notNull(),
  /** critical | high | medium | low — the highest severity among the NEW findings that triggered this. */
  severity: varchar("severity", { length: 16 }),
  title: text("title").notNull(),
  body: text("body").notNull(),
  isRead: boolean("is_read").notNull().default(false),
  createdAt: timestamp("created_at", { withTimezone: true })
    .notNull()
    .defaultNow(),
});

/**
 * One org's plan/billing state (Phase 6).
 *
 * `plan` is one of PLAN_IDS in src/lib/plans/limits.ts (free | starter |
 * professional | agency) — the example/configurable tiers from the
 * project spec, NOT validated market prices (see that file's header
 * comment). An org with no row here is treated as "free" by
 * src/lib/plans/limits.ts#getOrgPlan, so this table only needs a row once
 * an org actually changes plan or completes Stripe checkout.
 *
 * `status` mirrors Stripe subscription status ("active" | "trialing" |
 * "past_due" | "canceled" | "incomplete" | ...) for a Stripe-backed plan,
 * or "active" for a manually-set plan with no Stripe subscription at all.
 * `stripeCustomerId`/`stripeSubscriptionId` are set once a checkout
 * completes; see src/lib/billing/plan-sync.ts, which is the ONLY code
 * that should write to this table from a webhook.
 */
export const orgPlans = pgTable("org_plans", {
  organizationId: text("organization_id")
    .primaryKey()
    .references(() => organizations.id, { onDelete: "cascade" }),
  plan: varchar("plan", { length: 32 }).notNull().default("free"),
  status: varchar("status", { length: 32 }).notNull().default("active"),
  stripeCustomerId: text("stripe_customer_id"),
  stripeSubscriptionId: text("stripe_subscription_id"),
  currentPeriodEnd: timestamp("current_period_end", { withTimezone: true }),
  updatedAt: timestamp("updated_at", { withTimezone: true })
    .notNull()
    .defaultNow(),
});

/**
 * Idempotency ledger for processed Stripe webhook events (Phase 6).
 *
 * Stripe explicitly documents that a given webhook event can be
 * delivered more than once (retries on timeout/5xx, manual resend from
 * the dashboard, etc.) and that handlers must be written to tolerate
 * that. We record each event's id (Stripe's own `evt_...` id, globally
 * unique) the first time we successfully apply it; see
 * src/lib/billing/plan-sync.ts#applyStripeEvent, which checks this table
 * BEFORE touching org_plans and inserts into it atomically with that
 * update so a duplicate delivery is a no-op the second time.
 */
export const stripeEvents = pgTable("stripe_events", {
  id: text("id").primaryKey(),
  type: varchar("type", { length: 64 }).notNull(),
  processedAt: timestamp("processed_at", { withTimezone: true })
    .notNull()
    .defaultNow(),
});

/**
 * Lightweight audit trail (Phase 6). One row per meaningful tenant
 * action — see src/lib/audit/log.ts#logAudit, the single helper that
 * writes here (not an elaborate framework: callers pass a short
 * `action` string, the resource type/id it applied to, and a free-form
 * `metadata` blob for anything else worth keeping, e.g. the crawl job's
 * previous status). `actorUserId` is nullable because a scheduled crawl
 * firing (pg-boss's own cron, no human request) is still worth logging
 * but has no human actor.
 */
export const auditLog = pgTable("audit_log", {
  id: uuid("id").primaryKey().defaultRandom(),
  organizationId: text("organization_id")
    .notNull()
    .references(() => organizations.id, { onDelete: "cascade" }),
  actorUserId: text("actor_user_id").references(() => users.id, { onDelete: "set null" }),
  action: varchar("action", { length: 64 }).notNull(),
  targetType: varchar("target_type", { length: 32 }),
  targetId: text("target_id"),
  metadata: jsonb("metadata").notNull().default({}),
  createdAt: timestamp("created_at", { withTimezone: true })
    .notNull()
    .defaultNow(),
});
